//! Native textarea UTF-16 length follows trusted editor changes.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}

#[test]
fn textarea_text_length_actual_app_typing_paste_backspace_trusted_events_paint_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-textarea-text-length-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}#area{position:absolute;left:20px;top:80px;width:180px;height:60px}#check{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:160px;height:30px}#stable{position:absolute;left:420px;top:100px}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}</style><textarea id=area>Seed</textarea><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=paint></div><button id=check type=button>Check length</button><div id=destination></div><script>var x=document.getElementById('area'),events=0;x.oninput=function(e){if(!e.isTrusted||x.textLength!==x.value.length)throw 'trusted current length';events++;};document.getElementById('check').onclick=function(e){if(!e.isTrusted||x.value!=='😀A\n'||x.textLength!==4||x.defaultValue!=='Seed'||events!==3||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual native length';document.getElementById('paint').className='done';document.title='Textarea text length checked';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let area=node(&app,"area");let check=node(&app,"check");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+170)as usize*initial.width+430],0x114455);
 fn click(app:&mut App,node:usize){let rect=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
 click(&mut app,area);app.key(0x41,true,false,false);app.text_input('😀');app.paste("A\r\nB");app.key(0x08,false,false,false);assert_eq!(app.forms.controls[&area].value.text(),"😀A\n");click(&mut app,check);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Textarea text length checked");let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+170)as usize*painted.width+430],0xcc2244);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);
}
